def top_k_frequent(nums, k):
    counts = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1

    buckets = [[] for _ in range(len(nums) + 1)]
    for val, count in counts.items():
        buckets[count].append(val)

    result = []
    for count in range(len(buckets) - 1, 0, -1):
        for val in buckets[count]:
            result.append(val)
            if len(result) == k:
                return result
    return result

